/* -----------------------------------------------------------------------
 * delete_confirm.c
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tony's display/UI subsystem (best-ui), with an AI coding assistant.
 * BJT2 Sound Modulating Toy — Delete "Tap Again" Confirm
 *
 * Two states, IDLE and ARMED; delete_confirm.h has the table of what
 * moves between them. Every time is an unsigned difference of tick
 * counts, so the rules keep working when the 32-bit count wraps.
 *
 * No HAL functions are called. This file compiles on any host.
 * ----------------------------------------------------------------------- */

#include "delete_confirm.h"
#include <stdio.h>
#include <string.h>

/* The name, cut to 12 characters and always ended (an 8.3 name never has
 * more); "" for NULL. */
static void copy_name(char out[DC_NAME_LEN], const char *name)
{
    memset(out, 0, DC_NAME_LEN);
    if (name == NULL) {
        return;
    }
    for (size_t i = 0U; i < DC_NAME_LEN - 1U && name[i] != '\0'; i++) {
        out[i] = name[i];
    }
}

static bool same_name(const char *a, const char *b)
{
    return strncmp(a, b, DC_NAME_LEN) == 0;
}

/* A first tap: armed for name, counting from now_ms. */
static dc_press_t arm(delete_confirm_t *dc, uint32_t now_ms, const char *name)
{
    dc->state    = DC_ARMED;
    dc->armed_ms = now_ms;
    copy_name(dc->name, name);
    return DC_PRESS_ARMED;
}

void dc_init(delete_confirm_t *dc)
{
    if (dc == NULL) {
        return;
    }
    memset(dc, 0, sizeof(*dc));
    dc->state = DC_IDLE;
}

dc_press_t dc_press(delete_confirm_t *dc, uint32_t now_ms, const char *name,
                    char armed_out[DC_NAME_LEN])
{
    if (dc == NULL || name == NULL || name[0] == '\0') {
        return DC_PRESS_IGNORED;                /* nothing selected: nothing to delete */
    }
    if (dc->state != DC_ARMED) {
        return arm(dc, now_ms, name);
    }

    uint32_t since_ms = now_ms - dc->armed_ms;  /* wrap-safe */
    if (since_ms >= DC_CONFIRM_MS || !same_name(name, dc->name)) {
        return arm(dc, now_ms, name);           /* too late, or another file: a new first tap */
    }
    if (since_ms < DC_MIN_MS || armed_out == NULL) {
        return DC_PRESS_IGNORED;                /* too soon: still armed */
    }
    memcpy(armed_out, dc->name, DC_NAME_LEN);   /* the ARMED name, not whatever is shown now */
    dc->state = DC_IDLE;
    return DC_PRESS_CONFIRMED;
}

bool dc_update(delete_confirm_t *dc, uint32_t now_ms)
{
    if (dc == NULL || dc->state != DC_ARMED) {
        return false;
    }
    if ((uint32_t)(now_ms - dc->armed_ms) < DC_CONFIRM_MS) {
        return false;
    }
    dc->state = DC_IDLE;                        /* no second tap in time */
    return true;
}

void dc_name_changed(delete_confirm_t *dc, const char *name)
{
    char now_selected[DC_NAME_LEN];

    if (dc == NULL || dc->state != DC_ARMED) {
        return;
    }
    copy_name(now_selected, name);
    if (!same_name(now_selected, dc->name)) {
        dc->state = DC_IDLE;
    }
}

void dc_cancel(delete_confirm_t *dc)
{
    if (dc == NULL) {
        return;
    }
    dc->state = DC_IDLE;
}

bool dc_armed(const delete_confirm_t *dc)
{
    return (dc != NULL) && (dc->state == DC_ARMED);
}

const char *dc_label(const delete_confirm_t *dc)
{
    return dc_armed(dc) ? "Sure? Tap again" : "Delete";
}

void dc_prompt(const char *name, char *out, size_t len)
{
    if (out == NULL || len == 0U) {
        return;
    }
    /* "%.12s": an 8.3 name is 12 characters at most, so the line is 20 */
    snprintf(out, len, "Delete %.12s?", (name != NULL) ? name : "");
}
